(function () {
  var result = { sources: $.sources, advisories: $.advisories, upgrade: $.upgrade,
                 transitiveDependencies: $.transitiveDependencies };
  // A version deps.dev doesn't know would otherwise look clean.
  if (!$.sources || !$.sources.dependencyGraph) {
    result.warning = "deps.dev has no data for this version; it may not exist, so this result proves nothing";
  } else if (!$.sources.osv) {
    result.warning = "OSV.dev was unavailable, so the package's own advisories are unknown";
  }
  return result;
})();
